insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('photos','photos',false,26214400,array['image/webp']) on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create policy read_private_photos on storage.objects for select to authenticated using(bucket_id='photos' and exists(select 1 from public.photos p where (p.storage_path=name or p.thumb_path=name) and p.deleted_at is null and public.is_member(p.space_id) and (p.uploaded_by=auth.uid() or p.visibility='shared')));
create policy upload_private_photos on storage.objects for insert to authenticated with check(bucket_id='photos' and (storage.foldername(name))[1] in (select space_id::text from public.space_members where user_id=auth.uid()) and (storage.foldername(name))[2] ~ '^[0-9a-f-]{36}$' and storage.filename(name) in ('full.webp','thumb.webp'));
create policy cleanup_own_uploads on storage.objects for delete to authenticated using(bucket_id='photos' and owner_id=auth.uid()::text);
do $$begin alter publication supabase_realtime add table public.notifications, public.tasks, public.calendar_events; exception when duplicate_object then null;end $$;
